import Link from "next/link";
import { buildClient } from "../../api/build-client";

export default function OrderIndex({ orders, fetchError }) {
  if (fetchError) {
    return (
      <div className="container">
        <h1>My orders</h1>
        <div className="alert alert-warning">{fetchError}</div>
      </div>
    );
  }

  return (
    <div className="container">
      <h1>My orders</h1>
      {!orders?.length ? (
        <p>You have no orders yet.</p>
      ) : (
        <table className="table">
          <thead>
            <tr>
              <th>Ticket</th>
              <th>Price</th>
              <th>Status</th>
              <th></th>
            </tr>
          </thead>
          <tbody>
            {orders.map((order) => (
              <tr key={order.id}>
                <td>{order.ticket?.title ?? "—"}</td>
                <td>${order.ticket?.price ?? "—"}</td>
                <td>{order.status}</td>
                <td>
                  <Link href={`/orders/${order.id}`}>View</Link>
                </td>
              </tr>
            ))}
          </tbody>
        </table>
      )}
    </div>
  );
}

OrderIndex.getInitialProps = async (context) => {
  const client = buildClient(context);
  try {
    const { data } = await client.get("/api/orders");
    const orders = Array.isArray(data) ? data : [];
    return { orders };
  } catch {
    return {
      orders: [],
      fetchError:
        "Could not load orders. Sign in and ensure the orders service is reachable.",
    };
  }
};
